import{_ as s,a0 as l,w as a,s as d,ao as i,I as p,x as t,a1 as r,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"一張在75年前開啓了複印機時代的紙 | LCTT x X-CMD","titleTemplate":false,"description":"一張在75年前開啓了複印機時代的紙 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一張在75年前開啓了複印機時代的紙 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一張在75年前開啓了複印機時代的紙 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/How This 75 Year-Old Piece of Paper Started Modern Computing","title":"一張在75年前開啓了複印機時代的紙","tag":"201310","desc":""},"relativePath":"201310/How This 75 Year-Old Piece of Paper Started Modern Computing.md","filePath":"[post].md"}'),m={name:"201310/How This 75 Year-Old Piece of Paper Started Modern Computing.md"};function u(T,e,C,f,g,w){const o=l("Link");return a(),d("div",null,[e[19]||(e[19]=i('<h1 id="一張在75年前開啓了複印機時代的紙" tabindex="-1">一張在75年前開啓了複印機時代的紙 <a class="header-anchor" href="#一張在75年前開啓了複印機時代的紙" aria-label="Permalink to “一張在75年前開啓了複印機時代的紙”">​</a></h1><p><img src="http://rack.1.mshcdn.com/media/ZgkyMDEzLzEwLzEzL2VhL1hlcm94LjM4ODIwLmpwZwpwCXRodW1iCTk1MHg1MzQjCmUJanBn/2f9f894a/5ef/Xerox.jpg" alt="img"></p><p>1938年10月22曰，紐約市皇后區阿斯托里亞的一間公寓內，專利代理人卡爾遜（Chester Carlson）和無所事事的奧地利物理學家柯乃伊（Otto Kornei）利用週六的一個上午製作了世界上第一張乾式複印件(卡爾遜經過3年研究，在1938年成功實現世界上第一個靜電覆印實驗——譯者注)，從此開創了計算機的新時代！這是一個改變世界的時刻，這是一個激動人心的時刻！然後他們就去吃午餐了:D</p><p>75年來，複印產業成了美國公司的中流砥柱。即使在平板電腦和PDF大行其道的今天，去年一年時間，“多功能打印機”銷量為1900萬台，交易額為309億美元(來自Gartner公司的數據)。你也許忘了上次使用打印機是在什麼時候了，但IDC分析師Angèle Boyd指出,去年全球打印了3萬億張紙，其中１萬億張來自美國。在一些公司裏，一個員工每個月打印300到400張紙是再平常不過的事了。打印機生意保持令人吃驚的強大，其革命性已經遠超當年卡爾遜剛發明模擬式靜電覆印機的時候了。</p><p>靜電打印機提升了企業的生產力，增強了商務交流。Gartner 公司負責調查、繪圖和打印業務的副總裁Ken Weilerstein指出，大部分白領的工作任務就是以各種各樣的形式閲讀和創建文檔。Web原本是基於超文本，鏈接計算機上文檔的一種方法，後來由Tim Burners-Lee在1991年將其引入到互聯網。</p><p>Ken Weilerstein説：“打印機改變了人們處理文檔的方式，在人類的辦公史上，這可是一件大事。”</p><p>##施樂的崛起</p><p>施樂(Xerox)稱得上是最有名的打印機公司，在打印機市場持很大的佔有率。就像人們談搜索時會説“上網google一下”，談到打印時會説“我需要xerox（複印）這份文檔”，施樂公司已經滲入人們的日常生活中了。在科技領域，20世紀70年代，施樂由於在帕羅奧多研究中心（PARC）發明的用户圖形界面和鼠標而聲名遠揚，喬幫主當年參觀PARC後將很多點子用到了他的蘋果機上（其中一個就是PARC研發的圖形用户界面——譯者注）。另外，激光打印機也借鑑了卡爾遜的發明。</p><p>剛開始，施樂並不叫施樂。位於紐約市康涅狄格州羅切斯特市的哈洛伊德（Haloid）公司看中靜電打印技術，收購了卡爾遜的這項發明，之後才更名為“施樂”(在這中間，哈洛伊德還曾更名為“哈洛伊德施樂”——譯者注)。</p><p>我們繼續卡爾遜的故事，這位發明家和專利代理人對手工複印法律文件感到無比厭煩，他認為世上肯定有一種複印方法能讓他擺脱油墨複寫紙，或者那種傳統使用濕的感光紙和水的又亂又慢還昂貴的照相法。 施樂公司的歷史檔案管理員Ray Brewer説卡爾遜的這個涉及鋅片鋅粉（估計是作為感光材料——譯者注）的發明即簡單又容易複製。</p><p>（Weilerstein解釋説，靜電覆印的處理過程就是這麼個回事：一張紙放在光源底下，光源會掃描整張紙，記下複印原件的信息。光線通過一組透鏡照到塗有光敏材料的靜電成像硒鼓上，硒鼓被曝光部分會改變其靜電荷，複印原件的信息被複制到硒鼓上。之後硒像旋轉，靜電荷所在的地方會吸引墨粉微粒，從而在硒鼓上畫出原件圖像。然後硒鼓將墨粉轉移到一張紙上，並加壓加熱，就像熨斗一樣。最後，硒鼓旋轉，多餘的墨粉被刮下來，下一頁依此循環。）</p><p>或許這個過程太簡單了點。當卡爾遜在慶祝他們的突破時，柯乃伊並沒有看到這一點。當柯乃伊與卡爾遜的合同到期後，他們就失去了聯繫。“柯乃伊沒看到卡爾遜發明的意義”，Brewer説道。柯乃伊將會終身後悔。<strong>後來卡爾遜給了柯乃伊100股施樂的股票，而柯乃伊馬上就把它們賣了，為此他少嫌了至少100萬美元。</strong></p><p>多年來，卡爾遜向多家公司推銷他的專利，包括IBM和柯達，但是沒人理他。Brewer認為，這是因為卡爾遜只是一個研發人員，而不是一個銷售人員：“卡爾遜推銷他的專利的方式非常枯燥和專業，這種方式對於將他的專利推銷到市場沒有任何幫助，即使是技術工程師也被卡爾遜的表達搞得迷迷糊糊”。</p><p>卡爾遜的大突破發生在1946年，哈洛伊德公司研發主管John Dessauer讀到了關於卡爾遜發明的文章。哈洛伊德本來是做照相紙的，“當時的照相領域發展非常迅速”，Brewer説。1948年，哈洛伊德為卡爾遜的發明找了一個比較容易記住的名字：靜電覆印技術（electrophotography）。公司打印部門定名為施樂（xerography），取希臘詞根“xeros（幹）”和“graphos（寫）”組成的新詞。</p><p>在20世紀50到60年代之間，施樂打印機成為辦公必備用品。這項改革節省了時間和金錢。以前，複印文檔的唯一方法就是使用影印機，那是相當雜亂和昂貴的操作，更糟糕的是，那種油墨紙一次最多隻能複製兩份。假如你想複印更多份，你必須重新打印一份出來，“並且秘書和領導希望所有的複印件都一模一樣，”Brewer又出來講話了。這就是施樂複印術的又一個好處：多份一模一樣的複印件。在email和即時通信出來之前，這種複印術為部門間交流提供機會。施樂複印術催生了備忘錄、辦公簡訊以及生日賀卡等新鮮玩意兒。</p>',15)),p("p",null,[e[1]||(e[1]=t("914型複印機是施樂公司最成功的產品。在60年代到70年代初，施樂共賣掉了超過20萬台這個型號的複印機，《財富》雜誌將它",-1)),r(o,{href:"http://money.cnn.com/2010/01/21/technology/xerox_copiers.fortune/index.htm"},{default:n(()=>[...e[0]||(e[0]=[t("評為",-1)])]),_:1}),e[2]||(e[2]=t("“美國史上最成功的產品”。Weilerstein稱施樂為“你後悔沒買它的股票”的公司。",-1))]),p("p",null,[e[4]||(e[4]=t("這是一部大概在1960年播出的廣告：",-1)),r(o,{href:"http://www.youtube.com/embed/kNGdqC7QJYI"},{default:n(()=>[...e[3]||(e[3]=[t("http://www.youtube.com/embed/kNGdqC7QJYI",-1)])]),_:1})]),e[20]||(e[20]=p("p",null,"##現代計算機時代",-1)),e[21]||(e[21]=p("p",null,"直到80年代PC機開始代替打字機，施樂複印機的瘋狂時代才告終結。人們依靠卡爾遜的發明創造了激光打印機，從此淘汰了功能單一的複印機。這個時候，已經沒有人會把施樂的機器簡單地稱為複印機了，它們早已變成多功能打印機。",-1)),e[22]||(e[22]=p("p",null,"而這還不是施樂公司生意上所面臨的唯一挑戰。70年代曰本公司提供了與施樂複印機同性能但更便宜的產品。Weilerstein説：施樂失去了複印機領域的壟斷地位，但憑藉其在激光打印機產業的發展，施樂依然站在科技的前沿。到90年代，施樂開發Docutech系統，這種技術讓你從打印機年代直接進入到印刷機年代。之後施樂又研發了iGen2000，這是種能彩印的激光打印機，能在1分鐘內打印100頁複印件。“然而在2000年之後的一段時間內，施樂公司再沒有突出的作為，”Weilerstein説道，“並且他們還遭遇經濟危機。”",-1)),p("p",null,[e[6]||(e[6]=t("施樂沒有像它在羅徹斯特的鄰居——伊士曼.柯達一樣遭遇打擊。其時的柯達",-1)),r(o,{href:"http://www.usatoday.com/story/money/business/2013/09/03/kodak-bankruptcy-ends/2759965/"},{default:n(()=>[...e[5]||(e[5]=[t("處於相當陰暗的時期",-1)])]),_:1}),e[7]||(e[7]=t("。",-1))]),e[23]||(e[23]=i('<p>部分原因是，與膠捲不同，文檔打印依然是一個高利潤的生意。還是有些部門，包括聯邦政府，這些部門的員工每個月需要打印上千份文檔。Weilerstein 承認隨着時代發展，打印業務將繼續下降：“打印業務也許是老一代的產品”，但是他又説，“但它還不會輕易消失。”</p><p>鑑於市場對多功能打印機的持續需求，慢慢強大起來的施樂終於有機會將自己轉型成數字文檔和服務的供應商。在過去的十年裏，這家公司為打印管理服務(MPS)生意做了大量基礎性工作。企業的所有有關打印的業務都可以外包給MPS來完成，減少了IT部門監控的任務。</p><p>然而隨着紙打印業務長期的持續下滑，施樂試着預測市場的走向。“現在的問題是他們接下來會怎麼做，”Weilerstein説，“他們會取消管理你的打印機的念頭，轉而為你提供另外一種服務：按你的意願幫你處理數字形式的文檔。”</p><p>“我認為IT部門實行無紙辦公是一個非常大的需求”，來自IDC（國際數據公司）的Boyd説，“很多公司，包括施樂，都在積極為他們提供解決方案。”</p><p>Weilerstein的觀點是當所有的交流都是依賴文檔時，施樂有機會成為“內容管理服務（MCS）”生意的領導者。這種服務能讓企業減少使用打印機。Weilerstein在白皮書上寫到：“雖然紙質文檔依舊是交流的有效載體，但是當員工將不同來源的信息打印成紙質文檔，並想將它們用於不同目的時，太多的文檔反而無法形成有效的交流。”</p><p>在廣播信息都是靠傳真接收的時代，MCS應該接受廣告訂單；或者提供一種方式，將化工廠員工隨手記下的筆記傳到可供查閲的數碼產品中。</p><p><img src="http://rack.3.mshcdn.com/media/ZgkyMDEzLzEwLzExLzUwL0NoZXN0ZXJDYXJsLjAyZTI2LmpwZwpwCXRodW1iCTEyMDB4OTYwMD4/a1da164c/352/Chester-Carlson.jpg" alt="img"></p><p>##卡爾遜的遺產</p><p>在推動無紙辦公的過程中，施樂不應該只是將它的生意轉型，還應該幫助企業內減少不必要的浪費。然而，施樂還面臨大量的競爭對手，最大的對手就是Adobe公司，PDF文檔格式的發明者。</p><p>Adobe過去是做桌面打印（即通過電腦等電子手段進行文檔編輯——譯者注）而非紙質打印的，似乎比施樂有天然的優勢。然後是蘋果公司，自己賴以生存的老技術被新技術取代後，能迅速變成新技術的領導者，這在歷史上是很罕見的。</p><p>即使施樂最終失敗了，卡爾遜在科技史上的貢獻也是毋庸置疑的。卡爾遜的其他發明：帶有流水溝的雨衣、洗鞋器等，但是他最重要的發明是一個證據，證明市場是如何回報人的堅持和開闊的視野。他的去世向我們闡明瞭我們對公眾人物的內在生活了解是如此的少。</p><p>1968年，卡爾遜和柯乃伊在阿斯托里亞的公寓內辛辛苦苦地發明靜電覆印技術的30年之後，卡爾遜從羅徹斯特家裏回到紐約，去參加一個商業會議。他發現離開會還有一些時間，於是他走進一家電影院觀看《騎虎人（He Who Rides a Tiger）》，主演是Tom Bell和Judi Dench。當電影結束時，一個服務員看見了卡爾遜，看起來似乎正在位子上睡覺，事實並非如此。卡爾遜因心臟病去世——那是他那年第二次心臟病發作。</p><p>他死後，人們估計他擁有大約1.5億美元的遺產，這筆錢使他成為1968年全美最有錢的富翁之一。然而他們發現錯了，卡爾遜已將他的絕大部分財產都捐了出去。他曾對妻子説他對那種成為商業巨頭的野心表示很不理解，他只想作為一個窮人死去。</p><p>圖片來源：施樂公司</p><hr>',15)),p("p",null,[e[9]||(e[9]=t("via: ",-1)),r(o,{href:"http://mashable.com/2013/10/13/xerox-history-of-copying/"},{default:n(()=>[...e[8]||(e[8]=[t("http://mashable.com/2013/10/13/xerox-history-of-copying/",-1)])]),_:1})]),p("p",null,[e[12]||(e[12]=t("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創翻譯，",-1)),r(o,{href:"http://linux.cn/"},{default:n(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))]),p("p",null,[e[17]||(e[17]=t("譯者：",-1)),r(o,{href:"https://github.com/chenjintao"},{default:n(()=>[...e[15]||(e[15]=[t("chenjintao",-1)])]),_:1}),e[18]||(e[18]=t(" 校對：",-1)),r(o,{href:"https://github.com/jasminepeng"},{default:n(()=>[...e[16]||(e[16]=[t("jasminepeng",-1)])]),_:1})])])}const y=s(m,[["render",u]]);export{L as __pageData,y as default};
